function demoMain(idx,label){
  var calls=[];var mock={get:function(u){calls.push("GET "+u);return {status:200,body:"ok-"+(idx+1)};}};
  var r1=mock.get("/users");var r2=mock.get("/orders");
  return "["+label+"] mocked HTTP: "+calls.length+" calls recorded, last status="+r2.status+" body='"+r2.body+"'";
}

